from __future__ import annotations

import math
import threading
import uuid
from pathlib import Path
from typing import Any

from .embedding import EMBEDDING_DIMENSION


COLLECTION_NAME = "opera_chunks"


def point_id(chunk_id: str) -> str:
    return str(uuid.uuid5(uuid.NAMESPACE_URL, "xijing-ai:chunk:" + chunk_id))


class VectorStore:
    def __init__(self, path: Path, dimension: int = EMBEDDING_DIMENSION) -> None:
        if not isinstance(dimension, int) or isinstance(dimension, bool) or dimension < 1:
            raise ValueError("向量维度无效。")
        from qdrant_client import QdrantClient, models

        self.path = Path(path).resolve()
        self.dimension = dimension
        self._owner_thread = threading.get_ident()
        self._closed = False
        self._models = models
        self._client = QdrantClient(path=str(self.path))
        try:
            if not self._client.collection_exists(COLLECTION_NAME):
                self._client.create_collection(
                    collection_name=COLLECTION_NAME,
                    vectors_config=models.VectorParams(size=dimension, distance=models.Distance.COSINE),
                )
            else:
                vectors = self._client.get_collection(COLLECTION_NAME).config.params.vectors
                if isinstance(vectors, dict) or vectors is None:
                    raise ValueError("已有索引的向量配置与当前模型不兼容。")
                if vectors.size != dimension or vectors.distance != models.Distance.COSINE:
                    raise ValueError("已有索引的维度或距离与当前模型不兼容，请重建索引。")
        except Exception:
            self._client.close()
            self._closed = True
            raise

    def _ensure_open(self) -> None:
        if self._closed:
            raise RuntimeError("本地向量存储已关闭。")
        if threading.get_ident() != self._owner_thread:
            raise RuntimeError("本地向量存储必须由创建它的同一线程使用。")

    def _vector(self, vector: list[float]) -> list[float]:
        if not isinstance(vector, (list, tuple)) or len(vector) != self.dimension:
            raise ValueError("向量维度与索引不一致。")
        try:
            values = [float(value) for value in vector]
        except (TypeError, ValueError) as exc:
            raise ValueError("向量必须由数值组成。") from exc
        if not all(math.isfinite(value) for value in values) or not any(values):
            raise ValueError("向量必须有限且非零。")
        return values

    def upsert(self, chunks: list[dict[str, Any]], vectors: list[list[float]]) -> None:
        self._ensure_open()
        if len(chunks) != len(vectors):
            raise ValueError("片段数量与向量数量不一致。")
        points = []
        for chunk, vector in zip(chunks, vectors):
            required = ("chunk_id", "source_id", "document_version", "section_id")
            if any(not isinstance(chunk.get(key), str) or not chunk[key].strip() for key in required):
                raise ValueError("片段缺少真实的 ID 或版本元数据。")
            payload = {key: chunk[key] for key in required}
            if chunk.get("category") is not None:
                payload["category"] = chunk["category"]
            points.append(
                self._models.PointStruct(
                    id=point_id(chunk["chunk_id"]), vector=self._vector(vector), payload=payload
                )
            )
        if points:
            self._client.upsert(collection_name=COLLECTION_NAME, points=points, wait=True)

    def search(
        self, vector: list[float], limit: int = 5, category: str | None = None
    ) -> list[dict[str, Any]]:
        self._ensure_open()
        if not isinstance(limit, int) or isinstance(limit, bool) or not 1 <= limit <= 10:
            raise ValueError("检索数量必须在 1 到 10 之间。")
        query_filter = None
        if category is not None:
            if not isinstance(category, str) or not category.strip():
                raise ValueError("检索分类不能为空。")
            query_filter = self._models.Filter(
                must=[self._models.FieldCondition(key="category", match=self._models.MatchValue(value=category))]
            )
        response = self._client.query_points(
            collection_name=COLLECTION_NAME,
            query=self._vector(vector),
            limit=limit,
            query_filter=query_filter,
            with_payload=True,
            with_vectors=False,
        )
        result = []
        for point in response.points:
            payload = point.payload or {}
            chunk_id = payload.get("chunk_id")
            if not isinstance(chunk_id, str) or not chunk_id:
                raise RuntimeError("向量检索结果缺少片段关联，请核查索引。")
            result.append({**payload, "chunk_id": chunk_id, "score": float(point.score)})
        return result

    def count(self) -> int:
        self._ensure_open()
        return self._client.count(collection_name=COLLECTION_NAME, exact=True).count

    def close(self) -> None:
        if self._closed:
            return
        self._ensure_open()
        self._client.close()
        self._closed = True

    def __enter__(self) -> VectorStore:
        self._ensure_open()
        return self

    def __exit__(self, *_: Any) -> None:
        self.close()

"""Deterministic chapter/sentence chunking with a real-tokenizer budget."""

from __future__ import annotations

import hashlib
import re
import unicodedata
from typing import Any, Protocol

from .embedding import MAX_DOCUMENT_TOKENS


class TokenCounter(Protocol):
    def token_count(self, text: str) -> int: ...


def _sha256(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def _normalize(text: str) -> str:
    text = unicodedata.normalize("NFC", text).replace("\r\n", "\n").replace("\r", "\n")
    text = re.sub(r"[^\S\n]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


class Chunker:
    def __init__(
        self,
        embedding: TokenCounter,
        target_chars: int = 350,
        overlap_chars: int = 70,
        max_tokens: int = MAX_DOCUMENT_TOKENS,
    ) -> None:
        if target_chars < 1 or overlap_chars < 0 or not 1 <= max_tokens <= MAX_DOCUMENT_TOKENS:
            raise ValueError("分块参数无效。")
        self.embedding = embedding
        self.target_chars = target_chars
        self.overlap_chars = overlap_chars
        self.max_tokens = max_tokens

    def split_sections(
        self,
        source_id: str,
        version: str,
        sections: list[dict[str, Any]],
        category: str | None = None,
    ) -> list[dict[str, Any]]:
        if not isinstance(source_id, str) or not source_id.strip():
            raise ValueError("资料 source_id 不能为空。")
        if not isinstance(version, str) or not version.strip():
            raise ValueError("资料 document_version 不能为空。")
        if not isinstance(sections, list):
            raise ValueError("资料 sections 必须是列表。")
        chunks: list[dict[str, Any]] = []
        seen: set[str] = set()
        for ordinal, section in enumerate(sections, start=1):
            if not isinstance(section, dict) or not isinstance(section.get("content"), str):
                raise ValueError("资料章节必须包含文本 content。")
            content = _normalize(section["content"])
            if not content:
                continue
            title = section.get("title") or section.get("section")
            if not isinstance(title, str) or not title.strip():
                raise ValueError("资料章节必须包含真实标题。")
            title = title.strip()
            section_id = section.get("section_id") or section.get("id")
            if not section_id:
                section_id = "section_" + _sha256(f"{source_id}\n{ordinal}\n{title}")[:24]
            if not isinstance(section_id, str):
                raise ValueError("章节 section_id 必须是文本。")
            locator = section.get("locator") or title
            if not isinstance(locator, str):
                raise ValueError("章节 locator 必须是文本。")
            entities = section.get("entity_names", [])
            if not isinstance(entities, list) or any(not isinstance(item, str) for item in entities):
                raise ValueError("章节 entity_names 必须是文本列表。")
            bodies = self._bodies(content)
            previous = ""
            for index, body in enumerate(bodies, start=1):
                tail = previous[-self.overlap_chars:] if self.overlap_chars else ""
                while tail and self.embedding.token_count(tail + "\n" + body) > self.max_tokens:
                    tail = tail[1:]
                chunk_content = (tail + "\n" + body).strip() if tail else body
                previous = body
                content_hash = _sha256(chunk_content)
                if content_hash in seen:
                    continue
                seen.add(content_hash)
                chunk_id = "chunk_" + _sha256(f"{source_id}\n{section_id}\n{content_hash}")
                chunks.append(
                    {
                        "chunk_id": chunk_id,
                        "source_id": source_id,
                        "document_version": version,
                        "content_hash": content_hash,
                        "content": chunk_content,
                        "section_id": section_id,
                        "section": title,
                        "locator": f"{locator} · 入库片段 {index}/{len(bodies)}",
                        "category": category if category is not None else section.get("category"),
                        "entity_names": list(dict.fromkeys(entities)),
                        "token_count": self.embedding.token_count(chunk_content),
                    }
                )
        return chunks

    def _bodies(self, text: str) -> list[str]:
        sentences = [part.strip() for part in re.split(r"(?<=[。！？!?；;])|\n+", text) if part.strip()]
        units: list[str] = []
        for sentence in sentences:
            units.extend(self._split_long(sentence))
        result: list[str] = []
        current = ""
        for unit in units:
            candidate = current + "\n" + unit if current else unit
            if current and (
                len(current) >= self.target_chars
                or self.embedding.token_count(candidate) > self.max_tokens
            ):
                result.append(current)
                current = unit
            else:
                current = candidate
        if current:
            result.append(current)
        return result

    def _split_long(self, text: str) -> list[str]:
        parts: list[str] = []
        remaining = text
        while remaining:
            if self.embedding.token_count(remaining) <= self.max_tokens:
                parts.append(remaining)
                break
            # Find the largest safe prefix, then prefer a nearby word/phrase
            # boundary. A long sentence has no permission to truncate evidence.
            low, high = 1, len(remaining)
            end = 0
            while low <= high:
                middle = (low + high) // 2
                if self.embedding.token_count(remaining[:middle]) <= self.max_tokens:
                    end = middle
                    low = middle + 1
                else:
                    high = middle - 1
            if end == 0:
                raise ValueError("分块 token 预算不足以容纳一个字符。")
            boundaries = list(re.finditer(r"[，、,：:\s]", remaining[:end]))
            if boundaries and boundaries[-1].end() >= end // 2:
                end = boundaries[-1].end()
            part = remaining[:end].strip()
            if part:
                parts.append(part)
            remaining = remaining[end:].lstrip()
        return parts

